// reproduce-no-fcp.js
// A standalone Node script that imports our TraceOfTab computed artifact
// and feeds it the "no_fcp" trace fixture (airhorner_no_fcp.json) to trigger the NO_FCP error.

const fs = require('fs');
const path = require('path');
const TraceOfTab = require('lighthouse/lighthouse-core/computed/trace-of-tab.js');

(async () => {
  // Load the trace fixture that has no firstContentfulPaint event
  const tracePath = path.join(__dirname, 'airhorner_no_fcp.json');
  const trace = JSON.parse(fs.readFileSync(tracePath, 'utf8'));

  const context = { computedCache: new Map() };
  try {
    const result = await TraceOfTab.request(trace, context);
    console.log('Unexpected success:', result);
  } catch (err) {
    console.error('Caught expected error:');
    console.error('  code:', err.code);
    console.error('  message:', err.friendlyMessage || err.message);
    process.exit(err.code === 'NO_FCP' ? 0 : 1);
  }
})();
